.checkbox {
  --box-size: 1.25rem;   /* md default; sm/lg below */
  /* The label IS the target, and at 20px (17 on sm) it was under the SC 2.5.8
   * floor — and checkboxes stack, so the spacing exception does not apply. */
  min-block-size: var(--space-6);
  /* The hidden input below is absolutely positioned, so the label has to be its
   * containing block. Without this it resolves against the page instead, escapes
   * the clip of any scroll container it sits in, and stretches the DOCUMENT down
   * to its own offset — a page-tall form scrolled a few pixels and showed a white
   * strip under a shell that is exactly 100dvh tall. */
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  cursor: pointer;
  font-size: var(--font-base);
  color: var(--foreground);
  line-height: var(--leading-snug);
}
.checkbox[data-size="sm"] { --box-size: 1rem; font-size: var(--font-sm); }
.checkbox[data-size="lg"] { --box-size: 1.5rem; font-size: var(--font-md); }
.checkbox[data-disabled] { opacity: 0.5; cursor: not-allowed; }
/* The same three answers every other control gives. The selection family gave
 * none of them: a checkbox did not acknowledge the pointer, did not answer the
 * press, and had no way to be marked wrong — so a required consent box could be
 * rejected by a form with nothing on screen saying which box was the problem. */
.checkbox:hover:not([data-disabled]) .checkbox-box { border-color: var(--ring); }
.checkbox:active:not([data-disabled]) .checkbox-box { border-color: var(--primary-active); }
.checkbox[data-invalid] .checkbox-box { border-color: var(--destructive); }
.checkbox[data-invalid] .checkbox-input:focus-visible + .checkbox-box { outline-color: var(--destructive); }


/* Real input kept in the DOM (form-native + accessible), visually hidden. */
.checkbox-input { position: absolute; width: 1px; height: 1px; opacity: 0; margin: 0; }

.checkbox-box {
  position: relative;
  display: inline-grid;
  place-items: center;
  flex-shrink: 0;
  width: var(--box-size);
  height: var(--box-size);
  border: 1.5px solid var(--border-strong, var(--border));
  border-radius: var(--radius-sm);
  background: var(--background);
  color: var(--primary-foreground);
  transition: background var(--duration-fast), border-color var(--duration-fast);
}
.checkbox-box .icon { opacity: 0; transition: opacity var(--duration-fast); }

.checkbox-input:checked + .checkbox-box,
.checkbox-input:indeterminate + .checkbox-box { background: var(--primary); border-color: var(--primary); }
.checkbox-input:checked + .checkbox-box .icon { opacity: 1; }
/* Indeterminate dash (no minus icon in the set, so draw a bar). */
.checkbox-input:indeterminate + .checkbox-box::after {
  content: "";
  position: absolute;
  width: 60%;
  height: 2px;
  border-radius: 1px;
  background: var(--primary-foreground);
}
.checkbox-input:focus-visible + .checkbox-box {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

import './Checkbox.css'
import type { InputHTMLAttributes } from 'react'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'

type Props = Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size'> & {
  /** Visible label beside the box. */
  label?: string
  /** Mixed state (e.g. "select all" when only some children are checked). */
  indeterminate?: boolean
  /** Box size: sm / md (default) / lg. */
  size?: 'sm' | 'md' | 'lg'
  /** The form rejected this box (an unticked required consent). Red border and
   *  a red focus ring; the message belongs to the `<Field>` around it. */
  invalid?: boolean
}

/* Custom checkbox: a real <input> (kept accessible + form-native) visually
 * replaced by a themed box. Sizing/colors come from tokens, like the controls. 
   *
   * Copy: the label is the positive statement the tick makes true — "Send me the
   * weekly digest", never "Do not send…". A negative label makes an unticked
   * box mean yes.
   */
export function Checkbox({ label, indeterminate = false, size, invalid, className, disabled, ...rest }: Props) {
  return (
    <label
      className={cn('checkbox', className)}
      data-size={size}
      data-disabled={disabled || undefined}
      data-invalid={invalid || undefined}
    >
      <input
        ref={(el) => { if (el) el.indeterminate = indeterminate }}
        type="checkbox"
        className="checkbox-input"
        disabled={disabled}
        aria-invalid={invalid || undefined}
        {...rest}
      />
      <span className="checkbox-box" aria-hidden="true"><Icon name="check" /></span>
      {label && <span className="checkbox-label">{label}</span>}
    </label>
  )
}

/* Same rhythm as .radio-group: the two are read as one family and a different
 * gap on each is the kind of drift nobody sees until they sit side by side. */
.checkbox-group { display: flex; flex-direction: column; gap: var(--space-2); }

import './CheckboxGroup.css'
import { cn } from '../lib/cn'
import { Checkbox } from './Checkbox'

type Option = { value: string; label: string; disabled?: boolean }

type Props = {
  /** The ticked values. */
  value: string[]
  onChange: (value: string[]) => void
  options: Option[]
  /** Accessible group label. A group of boxes with no name is a list of
   *  unrelated questions to a screen reader. */
  label: string
  /** The form rejected the group as a whole (nothing ticked in a required set). */
  invalid?: boolean
  size?: 'sm' | 'md' | 'lg'
  className?: string
}

/* The multi-select twin of `<RadioGroup>`: several boxes, one value array, one
 * group name. Kept beside Checkbox because it is the same control, grouped —
 * and because a set of boxes hand-stacked in a screen is the version that
 * always ships without the group label. */

/** A labelled group of checkboxes over one value array. Reach for it whenever
 *  more than one box answers the same question. */
export function CheckboxGroup({ value, onChange, options, label, invalid, size, className }: Props) {
  const toggle = (v: string) =>
    onChange(value.includes(v) ? value.filter((x) => x !== v) : [...value, v])

  return (
    /* `group`, not `radiogroup`: several answers are legal here, and the
     * keyboard model is plain Tab per box rather than arrow keys across one. */
    <div className={cn('checkbox-group', className)} role="group" aria-label={label}>
      {options.map((o) => (
        <Checkbox
          key={o.value}
          value={o.value}
          size={size}
          invalid={invalid}
          checked={value.includes(o.value)}
          disabled={o.disabled}
          onChange={() => toggle(o.value)}
          label={o.label}
        />
      ))}
    </div>
  )
}
